import java.util.*;
public class HomeApplianceEnergyReport { public static void main(String[]a){Scanner s=new Scanner(System.in);int n=s.nextInt();s.nextLine();double t=0;while(n-->0){String[] p=s.nextLine().split(" ");String x=p[0];boolean saver=p.length>2; if(saver&&(x.equals("FRIDGE")||x.equals("TV"))){System.out.println(x+": saver mode not supported");continue;}double power=x.equals("FRIDGE")?150:x.equals("AC")?1500:x.equals("TV")?100:500,units=power*Double.parseDouble(p[1])/1000;if(saver)units*=.75;double cost=units*8;t+=cost;System.out.printf("%s: Units=%.2f Cost=%.2f%n",x,units,cost);}System.out.printf("Total Cost: %.2f%n",t);}}
